module.exports = function(RED) {
  const SessionManager = require('kumva-insights/utils/session-manager');
  const ConfigManager = require('kumva-insights/utils/config-manager');
  const helpers = require('kumva-insights/utils/helpers');

  let globalSessionManager = null;

  class WebhookManager {
    constructor() {
      this.nodeRegistry = new Map();
    }
    registerWaitingNode(sessionKey, callback) {
      this.nodeRegistry.set(sessionKey, { callback });
    }
    unregisterWaitingNode(sessionKey) {
      this.nodeRegistry.delete(sessionKey);
    }
    getWaitingNode(sessionKey) {
      return this.nodeRegistry.get(sessionKey);
    }
  }

  async function initializeGlobals() {
    if (!globalSessionManager) {
      const configManager = new ConfigManager();
      globalSessionManager = new SessionManager(configManager.getRedisConfig());
      await globalSessionManager.initialize();
    }
    return { sessionManager: globalSessionManager };
  }

  function KumvaWaitForResponseNode(config) {
    RED.nodes.createNode(this, config);
    const node = this;
    const flowId = this.z || this.id;

    if (!RED._kumvaWebhookManagers) {
      RED._kumvaWebhookManagers = new Map();
    }

    node.on('input', async function(msg) {
      try {
        const { sessionManager } = await initializeGlobals();

        let webhookManager = RED._kumvaWebhookManagers.get(flowId);
        if (!webhookManager) {
          webhookManager = new WebhookManager();
          RED._kumvaWebhookManagers.set(flowId, webhookManager);
        }

        const sessionKey = msg.sessionKey || msg.sessionId || msg._kumva?.sessionKey || msg._kumva?.sessionId;
        if (!sessionKey) {
          return node.error('No sessionKey or sessionId');
        }

        const timeoutMs = helpers.getTimeoutMs(config.responseTimeout || config.timeout || '30s');
        let timeoutHandle = null;

        const callback = async (response) => {
          try {
            if (timeoutHandle) {
              clearTimeout(timeoutHandle);
              timeoutHandle = null;
            }

            const responseContent = response.content || response.text || response.message || response.dtmfInput || '';
            const responseData = {
              type: response.type || 'text',
              content: responseContent,
              rawData: response,
              receivedAt: new Date().toISOString()
            };

            await sessionManager.storeResponse(sessionKey, responseData);
            await sessionManager.updateSession(sessionKey, { lastResponse: responseData, status: 'awaiting' });

            let validation = true;
            if (config.validateResponse) {
              try {
                const rules = typeof config.validationRules === 'string'
                  ? helpers.safeJsonParse(config.validationRules, {})
                  : (config.validationRules || {});
                const value = responseContent;

                if (rules.minLength && value.length < rules.minLength) validation = false;
                if (rules.maxLength && value.length > rules.maxLength) validation = false;
                if (rules.pattern && !new RegExp(rules.pattern).test(value)) validation = false;
                if (rules.allowedValues && !rules.allowedValues.includes(value)) validation = false;
                if (rules.minValue !== undefined && Number(value) < Number(rules.minValue)) validation = false;
                if (rules.maxValue !== undefined && Number(value) > Number(rules.maxValue)) validation = false;
              } catch (e) {
                node.warn(`Validation parse error: ${e.message}`);
              }
            }

            if (validation) {
              node.send([{ ...msg, sessionKey, response: responseData, waitStatus: 'response-received' }, null, null]);
              node.status({ fill: 'green', shape: 'dot', text: 'Response received' });
            } else {
              node.send([null, { ...msg, sessionKey, response: responseData, validation: false, waitStatus: 'validation-failed' }, null]);
              node.status({ fill: 'orange', shape: 'dot', text: 'Validation failed' });
            }
          } catch (error) {
            node.error(`Callback: ${error.message}`);
          }
        };

        webhookManager.registerWaitingNode(sessionKey, callback);
        node.status({ fill: 'yellow', shape: 'dot', text: `Waiting: ${sessionKey}` });

        timeoutHandle = setTimeout(() => {
          webhookManager.unregisterWaitingNode(sessionKey);
          const timeoutAction = config.handleTimeout || 'continue';
          if (timeoutAction === 'retry') {
            node.send([null, { ...msg, sessionKey, timeout: true, waitStatus: 'timeout-retry' }, null]);
          } else if (timeoutAction === 'fallback') {
            node.send([null, null, { ...msg, sessionKey, timeout: true, waitStatus: 'timeout-fallback' }]);
          } else {
            node.send([{ ...msg, sessionKey, timeout: true, waitStatus: 'timeout' }, null, null]);
          }
          node.status({ fill: 'orange', shape: 'ring', text: 'Timeout' });
        }, timeoutMs);

        node._timeoutHandle = timeoutHandle;
      } catch (error) {
        node.error(`WaitForResponse: ${error.message}`);
        node.status({ fill: 'red', shape: 'ring', text: 'Error' });
      }
    });

    node.on('close', (done) => {
      if (node._timeoutHandle) {
        clearTimeout(node._timeoutHandle);
      }
      done();
    });
  }

  RED.nodes.registerType('kumva-wait-for-response', KumvaWaitForResponseNode);
};